password = "Robust!23"
attempts = 0
granted = False
while attempts < 3 and not granted:
    guess = input()
    attempts = attempts + 1
    if guess == password:
        granted = True
if granted:
    print("Access granted")
else:
    print("Locked out")

def is_valid_age(age):
    # An age is valid if it is from 0 to 120
    return age >= 0 and age <= 120

age = int(input())
if is_valid_age(age):
    print("Age OK")
else:
    print("Age not OK")

